        for (var i = 0; i < 3; i++)
        {
            s.Refused(W(5), AtmStatus.InvalidAmount);
            s.Refused(W(60), AtmStatus.DailyLimitExceeded);
            s.Refused(W(-10), AtmStatus.InvalidAmount);
            s.Refused(D(0, 0, 0), AtmStatus.InvalidAmount);
