mkdir -p /tmp/mut/chk && cd /tmp/mut/chk && cp -r /travail/Atm /travail/Atm.Contract . && rm -rf */bin */obj && mkdir -p Checker && cat > Checker/Checker.csproj <<'EOF'
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup><OutputType>Exe</OutputType><TargetFramework>net10.0</TargetFramework><Nullable>enable</Nullable><ImplicitUsings>enable</ImplicitUsings><Optimize>true</Optimize></PropertyGroup>
  <ItemGroup><ProjectReference Include="../Atm/Atm.csproj" /><ProjectReference Include="../Atm.Contract/Atm.Contract.csproj" /></ItemGroup>
</Project>
EOF
cat > Checker/Program.cs <<'EOF'
using Atm;
static NoteCounts N(int a,int b,int c)=>new(a,b,c);
var stocks = new List<NoteCounts>(); for(int a=0;a<=5;a++)for(int b=0;b<=5;b++)for(int c=0;c<=5;c++)stocks.Add(N(a,b,c));
Denomination?[] jams=[null,Denomination.Fifty,Denomination.Twenty,Denomination.Ten];
int[] amounts=[-10,0,5,..Enumerable.Range(1,22).Select(i=>i*10)];
var ops = new List<Operation>(); foreach(var a in amounts) ops.Add(new Operation.Withdraw(a));
for(int m=0;m<8;m++) ops.Add(new Operation.Deposit(N(m&1,(m>>1)&1,(m>>2)&1)));
NoteCounts Usable(NoteCounts s, Denomination? j)=> j switch{Denomination.Fifty=>s with{Fifties=0},Denomination.Twenty=>s with{Twenties=0},Denomination.Ten=>s with{Tens=0},_=>s};
NoteCounts? Best(int amount, NoteCounts av){ NoteCounts? best=null; foreach(var n in stocks){ if(n.Fifties<=av.Fifties&&n.Twenties<=av.Twenties&&n.Tens<=av.Tens&&n.Value==amount&&(best is null||n.Total<best.Value.Total)) best=n;} return best;}
var memo=new Dictionary<(NoteCounts,int),NoteCounts?>();
long total=0, diff=0; var examples=new List<string>();
foreach(var s in stocks) foreach(var j in jams) foreach(var op in ops) for(int B=0;B<=250;B+=5) for(int W=0;W<=200;W+=10){
  total++;
  var acc=new AccountState(B,W); AtmResult exp; NoteCounts expStock=s;
  AtmResult R(AtmStatus st)=>new(st,NoteCounts.None,0,acc);
  if(op is Operation.Withdraw{Amount:var a}){ int fee=a>100?5:0;
    if(a<=0||a%10!=0) exp=R(AtmStatus.InvalidAmount);
    else if(W+a>200) exp=R(AtmStatus.DailyLimitExceeded);
    else if(a+fee>B) exp=R(AtmStatus.InsufficientFunds);
    else { var key=(Usable(s,j),a); if(!memo.TryGetValue(key,out var c)) memo[key]=c=Best(a,key.Item1);
      if(c is not {} n) exp=R(AtmStatus.CannotDispense); else { exp=new(AtmStatus.Ok,n,fee,new(B-a-fee,W+a)); expStock=s-n; } }
  } else { var n=((Operation.Deposit)op).Notes; var af=s+n;
    if(n.Total==0) exp=R(AtmStatus.InvalidAmount);
    else if(j is {} jj && n.Of(jj)>0) exp=R(AtmStatus.CassetteJammed);
    else if(af.Fifties>5||af.Twenties>5||af.Tens>5) exp=R(AtmStatus.CassetteFull);
    else { exp=new(AtmStatus.Ok,NoteCounts.None,0,acc with{Balance=B+n.Value}); expStock=af; } }
  var d=new MoneyDispenser(s,j); AtmResult got; string err="";
  try{ got=new CashMachine(d).Execute(acc,op);}catch(Exception e){ got=default; err=e.GetType().Name; }
  if(got!=exp||d.Stock!=expStock){ diff++; if(examples.Count<8) examples.Add($"B={B} W={W} s={s} j={j} op={op} exp={exp} got={got}{err}"); }
}
Console.WriteLine($"diff {diff}/{total} = {100.0*diff/total:F3}%");
foreach(var e in examples) Console.WriteLine(e);
EOF
dotnet run -c Release --project Checker 2>&1 | tail -3

